import {cropReferences,referenceCards} from './crop-references.js';
export const sources=[{name:'SENASA · BPA del limón, pp. 4–5',url:'https://www.senasa.gob.pe/senasa/descargasarchivos/2020/07/Guia-BPA-LIMON.pdf',scope:'Historial, suelo, profundidad y drenaje para limón. No valida rotaciones anuales.'},{name:'INIA · Manejo integrado de mango Kent',url:'https://repositorio.inia.gob.pe/handle/20.500.12955/966',scope:'Referencia para revisión agronómica del mango en Piura; sin umbrales extraídos en esta versión.'}];
export function assessField(f,d={}){const missing=[],checks=[];const number=k=>typeof d[k]==='number'&&Number.isFinite(d[k])?d[k]:null;
for(const [key,label] of [['variety','Especie y variedad anual concreta'],['planting','Fecha prevista de siembra'],['waterDocument','Fuente de la dotación de agua'],['market','Comprador y costos estimados']])if(!d[key]?.trim())missing.push(label);
if(!d.date)missing.push('Fecha del análisis de suelo');if(!d.lab?.trim())missing.push('Laboratorio o responsable del análisis');
for(const [key,label] of [['ph','pH del suelo'],['depth','Profundidad efectiva del suelo (no profundidad de la muestra)']])if(number(key)===null)missing.push(label);
if(!['bueno','deficiente'].includes(d.drainage))missing.push('Drenaje observado');if(!d.history?.trim())missing.push('Historial de cultivos y plagas');if(!d.water?.trim())missing.push('Disponibilidad y calidad de agua documentadas');
if(f.crop?.includes('Limón')){if(number('ph')!==null)checks.push({rule:'L-S1',source:0,label:'pH para limón',status:d.ph<5||d.ph>8.5?'revisar':'referencia',text:d.ph<5||d.ph>8.5?'Fuera del rango aceptado descrito por SENASA. Revisar con el técnico; no indicar correcciones automáticas.':d.ph>=6&&d.ph<=7?'Dentro del intervalo favorable descrito por SENASA. Esto no confirma la aptitud completa.':'Dentro del rango aceptado, fuera del intervalo favorable de 6 a 7.'});if(number('depth')!==null)checks.push({rule:'L-S2',source:0,label:'Profundidad para limón',status:d.depth<100?'revisar':'referencia',text:d.depth<100?'Menos de un metro de suelo efectivo: revisar la limitación antes de instalar limón.':'Alcanza la referencia de un metro; faltan otros factores.'});if(d.drainage==='deficiente')checks.push({rule:'L-S3',source:0,label:'Drenaje para limón',status:'revisar',text:'El drenaje deficiente requiere evaluación; la guía relaciona suelos poco permeables con problemas de raíces.'});}
else checks.push({rule:'M-0',source:1,label:'Mango',status:'pendiente',text:'No se aplican los rangos de limón al mango. Se requiere una ficha técnica local validada para cultivar, variedad y etapa.'});
return {version:'field-assessment-1',status:missing.length?'Faltan evidencias':checks.some(x=>x.status==='revisar')?'Hay condiciones que revisar':'Expediente para revisión técnica',missing,checks,recommendation:'No hay autorización automática de siembra. Las rotaciones anuales del simulador siguen siendo ejemplos hasta validar especie, agua, suelo, antecedentes, calendario y mercado.',sources};}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountAssessment(host,f,context){host.innerHTML='<details class="assessment"><summary>🔎 Evaluar con datos de mi campo</summary><h3>Primero la evidencia. Después la decisión.</h3><p>Los satélites no confirman el pH, las plagas del lote ni tus turnos de riego. Registra el informe que ya tienes; dejar un dato vacío es mejor que inventarlo.</p><form class="fields"><label>Fecha de análisis<input name="date" type="date"></label><label>Laboratorio o responsable<input name="lab" maxlength="150"></label><label>pH de laboratorio<input name="ph" type="number" min="0" max="14" step="0.1"></label><label>Profundidad efectiva (cm)<input name="depth" type="number" min="0" max="1000"></label><label>Drenaje<select name="drainage"><option value="">No lo sé</option><option value="bueno">Bueno, observado en campo</option><option value="deficiente">Deficiente / se encharca</option></select></label><label>Historial de cultivos y plagas<textarea name="history" maxlength="2000"></textarea></label><label>Agua: turnos, volumen, calidad y fuente<textarea name="water" maxlength="2000"></textarea></label><label>Especie y variedad del cultivo anual<input name="variety" maxlength="150" placeholder="Indica especie y variedad"></label><label>Fecha prevista de siembra<input name="planting" type="date"></label><label>Fuente de la dotación de riego<input name="waterDocument" maxlength="250" placeholder="Documento, responsable y fecha"></label><label>Comprador, precio y costos estimados<textarea name="market" maxlength="2000"></textarea></label><button type="submit">Revisar mi evidencia</button></form><div class="crop-references"></div><div class="assessment-result" aria-live="polite"></div><button type="button" class="assessment-export">Descargar expediente para mi técnico</button><p>No se envían estos datos a un servidor. Descarga el expediente antes de salir.</p></details>';let data={},report;host.querySelector('.crop-references').innerHTML=referenceCards();
function update(){report=assessField(f,data);host.querySelector('.assessment-result').innerHTML='<h3>'+report.status+'</h3>'+report.missing.map(m=>'<p>○ Falta: '+esc(m)+'</p>').join('')+report.checks.map(r=>'<article><strong>'+esc(r.label)+'</strong><p>'+esc(r.text)+'</p><a target="_blank" rel="noopener" href="'+sources[r.source].url+'">'+sources[r.source].name+'</a></article>').join('')+'<p>'+report.recommendation+'</p>';}
host.querySelector('form').onsubmit=e=>{e.preventDefault();data=Object.fromEntries(new FormData(e.target));for(const k of ['ph','depth'])data[k]=data[k]===''?null:Number(data[k]);update();};host.querySelector('.assessment-export').onclick=()=>{const blob=new Blob([JSON.stringify({created:new Date().toISOString(),farm:f,evidence:data,assessment:report,cropReferences,climate:{source:context.source,rows:context.rows},prediction:context.prediction,provenance:'Datos agrícolas declarados por usuario, sin verificación independiente'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nortex-expediente-tecnico.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};update();}
